import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import *
t=register('r28'); c=lambda *a,**k: call(*a,tok=t,**k)
def rej(body, name, m=None, path='/partners'):
    try: c(path, body, m=m); ok(False, name)
    except E as e: ok('400' in str(e), name+' → '+str(e)[60:170])
cfg=call('/config'); ok(cfg.get('charity') is False and cfg.get('desktop') is False, 'config: charity off, not desktop')
try: c('/charity/settings'); ok(False,'charity api closed')
except E as e: ok('404' in str(e),'charity api closed (404)')
meta=c('/partners/meta'); ok('NAT' in meta['idTypes'] and len(meta['regions'])==13, 'meta: id types + 13 regions')
full={'name':'شركة الاختبار','kind':'COMPANY','isCustomer':True,'vatNumber':'310122393500003','crNumber':'4031234567','street':'طريق الملك عبدالعزيز','buildingNo':'1234','additionalNo':'5678','district':'العزيزية','city':'مكة المكرمة','postalCode':'24243','region':'مكة المكرمة','phone':'0541234567','email':'A@Test.sa','contactPerson':'أحمد'}
rej({**full,'buildingNo':'12'}, 'reject building no not 4 digits')
rej({**full,'postalCode':'2424'}, 'reject postal not 5 digits')
rej({**full,'vatNumber':'123'}, 'reject bad VAT')
rej({**full,'phone':'12345'}, 'reject bad phone')
rej({**full,'email':'x@'}, 'reject bad email')
rej({k:v for k,v in full.items() if k!='street'}, 'company customer missing street rejected')
rej({k:v for k,v in full.items() if k not in('vatNumber','crNumber')}, 'company customer without VAT or ID rejected')
rej({k:v for k,v in full.items() if k!='phone'}, 'company customer missing phone rejected')
p=c('/partners',{**full,'phone':'٠٥٤١٢٣٤٥٦٧','postalCode':'٢٤٢٤٣'}); ok(p['phone']=='0541234567' and p['postalCode']=='24243' and p['email']=='a@test.sa' and p['additionalNo']=='5678','arabic digits normalised, email lowercased, additional no saved')
g=c('/partners/'+p['id']); ok(g['taxReady'] and not g['taxMissing'],'full company customer taxReady')
nr=c('/partners',{**{k:v for k,v in full.items() if k not in ('vatNumber',)},'name':'جهة غير مسجلة','idType':'700','crNumber':None,'idNumber':'7001234567','vatExemptReason':'جهة حكومية'}); ok(nr['idType']=='700','non-VAT company with 700 id accepted')
rej({**{k:v for k,v in full.items() if k!='vatNumber'},'name':'x','idType':'NAT','idNumber':'2123456789','vatExemptReason':'أخرى'}, 'NAT must start with 1')
ind=c('/partners',{'name':'فرد','kind':'INDIVIDUAL','isCustomer':True,'phone':'0551112233'}); ok(ind['id'] and True,'individual with name+phone ok')
rej({'name':'فرد بلا جوال','kind':'INDIVIDUAL','isCustomer':True}, 'individual without phone rejected')
sup=c('/partners',{'name':'مورد','isSupplier':True,'kind':'COMPANY','strict':False}); ok(sup['id'] is not None,'supplier via import path (strict off) allowed')
ok(c('/partners/'+p['id'],{'isActive':False},m='PUT')['isActive']==False,'quick toggle on partner still works')
c('/partners/'+p['id'],{'isActive':True},m='PUT')
rej({**full,'street':''}, 'PUT form save clearing street rejected', m='PUT', path='/partners/'+p['id'])
lst=c('/partners?role=CUSTOMER&active=all'); ok(all('taxReady' in x for x in lst),'list returns taxReady')
fo=c('/partners',{'name':'Dubai Co','kind':'COMPANY','isCustomer':True,'country':'AE','vatNumber':None,'idType':'OTH','idNumber':'AE-99','vatExemptReason':'عميل خارج المملكة','street':'SZR','buildingNo':'12A','district':'DIFC','city':'Dubai','postalCode':'00000','phone':'+971501234567'}); ok(fo['country']=='AE','foreign customer free address format')
prod=c('/products',{'name':'خدمة','sku':'SV28','type':'SERVICE','salePrice':100,'purchasePrice':0,'taxCode':'S'})
inv=c('/invoices',{'direction':'SALE','kind':'INVOICE','partnerId':nr['id'],'date':'2026-11-01','lines':[{'productId':prod['id'],'qty':1,'unitPrice':100,'taxCode':'S'}]})
inv=c(f"/invoices/{inv['id']}/post",{'overrideCreditLimit':True}); ok(inv['status']=='POSTED','post invoice to non-VAT buyer with 700 id')
